(function(){
 const F=window.AGENTOS_FIXTURE,C=window.AGENTOS_CORE,key='agentos-micro-retail-v3';let s,modalTrigger;
 const t=(z,e)=>s.lang==='zh'?z:e,T=o=>t(o.zh,o.en),P=()=>C.plan(s),nt=n=>'NT$'+n.toLocaleString('zh-TW');
 const demoPlan={inquiry:true,inventory:true,externalApproval:true,manualInventory:true};
 function load(){try{let x=JSON.parse(localStorage.getItem(key)||'null');s=x?{...C.initial(x.lang||'zh'),...x,signals:{...C.initial().signals,...x.signals}}:C.initial()}catch(e){s=C.initial()}}
 function save(){try{localStorage.setItem(key,JSON.stringify(s))}catch(e){}}
 function act(a){s=C.reduce(s,a);save();render();if(s.toast)setTimeout(()=>{if(s.toast){s=C.reduce(s,'clearToast');save();render()}},3200)}
 function go(x,hash=true){s.screen=x;save();if(hash&&location.hash!=='#'+x)location.hash='#'+x;render()}
 function tag(type){let x={implemented:['原型已實作','Prototype implemented'],sim:['模擬 AI','Simulated AI'],rule:['確定性規則','Deterministic rule'],owner:['Owner 決策','Owner decision'],planned:['規劃能力','Planned capability'],preview:['固定資料預覽','Frozen-data preview']}[type];return `<span class="badge ${type}">${t(x[0],x[1])}</span>`}
 function esc(x){return String(x||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
 function nav(){return `<header class="topbar"><a class="brand" data-go="brief">Agent<span>OS</span></a><nav>${[['brief',t('商家設定','Business Brief')],['team',t('AI 工作團隊','My AI Team')],['owner',t('Owner 收件匣','Owner Inbox')],['pulse',t('營運脈動','Business Pulse')]].map(([id,n])=>`<button class="nav-btn ${s.screen===id?'active':''}" data-go="${id}">${n}</button>`).join('')}</nav><button class="reset" data-action="reset">${t('重設示範','Reset demo')}</button><button class="language" data-action="lang">${s.lang==='zh'?'EN':'繁中'}</button></header>`}
 function render(){document.documentElement.lang=s.lang==='zh'?'zh-Hant':'en';let root=document.getElementById('app');root.innerHTML=nav()+`<main class="shell">${s.screen==='brief'?brief():s.screen==='team'?team():s.screen==='owner'?owner():pulse()}</main>`}
 function futureDesks(){return `<section class="work-desk-strip"><div class="strip-head"><div><p class="eyebrow">${t('AgentOS Work Desk 架構','AGENTOS WORK DESK ARCHITECTURE')}</p><h2>${t('同一個核心，依工作方式建立不同的 AI 工作桌。','One core, different AI work desks for different work.')}</h2></div><span>${tag('planned')}</span></div><div class="desk-row"><button class="desk-card active" data-modal="retail"><small>${t('目前可操作','Interactive demo')}</small><b>${t('Retail Order Desk','Retail Order Desk')}</b><span>${t('分散詢問、訂單、庫存例外','Fragmented inquiries, orders, stock exceptions')}</span></button><button class="desk-card" data-modal="translator"><small>${t('未來 Work Desk','Future work desk')}</small><b>${t('Translation Delivery Desk','Translation Delivery Desk')}</b><span>${t('文件、術語、QA、交付','Documents, terminology, QA, delivery')}</span></button><button class="desk-card" data-modal="designer"><small>${t('未來 Work Desk','Future work desk')}</small><b>${t('Creative Project Desk','Creative Project Desk')}</b><span>${t('Brief、素材、feedback、交付','Briefs, assets, feedback, delivery')}</span></button></div></section>`}
 function signals(p){let rows=[];if(p.inquiry)rows.push(t('顧客詢問與訂單資訊分散，需要整理。','Customer inquiries and order information are fragmented and need triage.'));if(p.inventory)rows.push(t('市集與線上紀錄需要比對，避免可用量判斷失準。','Market and online records need comparison to prevent inaccurate availability decisions.'));if(p.externalApproval)rows.push(t('所有對外訊息與庫存異動均需 Owner 確認。','Every external message and inventory change requires Owner confirmation.'));return rows}
 function discovery(){let p=P(),rows=signals(p);return `<section class="discovery-grid"><div class="panel discovery"><div class="panel-title"><div><p class="eyebrow">${t('階段一 · 引導式商業探索','PHASE 1 · GUIDED BUSINESS DISCOVERY')}</p><h1>${t('先了解工作，再建立必要的 AI 工作能力。','Understand the work first, then build only necessary AI capabilities.')}</h1><p>${t('這是固定示範輸入，不是假裝理解自由對話。未來 live LLM 可在此追問、整理與產生方案。','These are frozen demo inputs, not pretend free-form understanding. A future live LLM can ask follow-ups, synthesize context, and create a plan here.')}</p></div>${tag('sim')}</div><div class="choice-grid"><button class="choice ${p.inquiry?'selected':''}" data-intent="inquiry"><b>${t('顧客詢問與訂單整理','Customer inquiry & order triage')}</b><span>${t('IG／LINE 待回覆容易漏掉，整理訂單很花時間。','IG/LINE replies are easy to miss and order triage takes time.')}</span></button><button class="choice ${p.inventory?'selected':''}" data-intent="inventory"><b>${t('市集與線上庫存協調','Market / online inventory reconciliation')}</b><span>${t('市集賣出後，試算表與線上可用量常不同步。','After market sales, spreadsheets and online availability often fall out of sync.')}</span></button><button class="choice ${p.externalApproval?'selected':''}" data-intent="control"><b>${t('Owner 保留更多控制','Owner keeps more control')}</b><span>${t('所有對外訊息須確認；庫存由本人決定是否更新。','Every external message needs review; the Owner decides on stock updates.')}</span></button></div><div class="discovery-actions"><button class="secondary" data-action="sample">${t('載入沐光手作示範情境','Load Muguang retail example')}</button>${s.ready?`<button class="primary" data-action="review">${t('查看商業診斷與工作方案 →','Review diagnosis & work plan →')}</button>`:''}</div></div><aside class="panel understanding"><div class="panel-title"><div><p class="eyebrow">${t('目前理解','CURRENT UNDERSTANDING')}</p><h2>${rows.length?t('商家目前的營運需要','Current operational needs'):t('先選擇一個示範需要','Choose a demo need first')}</h2></div>${tag('implemented')}</div>${rows.length?`<ul>${rows.map(x=>`<li>${x}</li>`).join('')}</ul>`:`<p class="muted">${t('選擇一個情境後，這裡會整理已確認需求、限制與下一步。','After you choose a scenario, this area summarizes confirmed needs, constraints, and next steps.')}</p>`}<div class="boundary"><b>${t('能力誠實標示','Capability boundary')}</b><p>${t('原型已實作有限輸入選擇與固定方案；自然語言追問、跨系統讀取與 live LLM 推理皆屬規劃能力。','The prototype implements limited input selection and frozen plans; natural-language follow-ups, cross-system reads, and live LLM reasoning are planned capabilities.')}</p></div></aside></section>`}
 function capCard(id,p){let f=F.proposals[id],kind=id==='inquiry'?'sim':'rule',bound=id==='inquiry'&&p.externalApproval?t('所有對外回覆維持草稿，需 Owner 確認。','All external replies remain drafts and need Owner review.'):id==='inventory'&&p.manualInventory?t('只提出差異與更新建議；Owner 決定是否異動。','Only surface differences and update suggestions; the Owner decides whether to change stock.'):T(f.boundary);return `<article class="cap-card"><div><h3>${T(f.name)}</h3>${tag(kind)}</div><p>${T(f.problem)}</p><dl><dt>${t('輸入','Input')}</dt><dd>${T(f.inputs)}</dd><dt>${t('工作成果','Work product')}</dt><dd>${T(f.output)}</dd><dt>${t('Owner 邊界','Owner boundary')}</dt><dd>${bound}</dd></dl></article>`}
 function review(){let p=P(),caps=[];if(p.inquiry)caps.push(capCard('inquiry',p));if(p.inventory)caps.push(capCard('inventory',p));return `<section class="brief-stage"><div class="page-head"><div><p class="eyebrow">${t('階段二 · 診斷與方案確認','PHASE 2 · DIAGNOSIS & PLAN REVIEW')}</p><h1>${t('Daily Order Desk：依商家需要形成的工作方案','Daily Order Desk: a work plan derived from merchant needs')}</h1><p>${t('這不是根因判定，而是根據已選情境形成的可檢視工作設計。','This is not a root-cause finding; it is an inspectable work design based on the selected demo needs.')}</p></div>${tag('sim')}</div><div class="insight-row"><article><h3>${tag('implemented')} ${t('已確認需求','Confirmed needs')}</h3><ul>${signals(p).map(x=>`<li>${x}</li>`).join('')}</ul></article><article><h3>${tag('sim')} ${t('工作假設','Working hypothesis')}</h3><p>${p.inventory?t('分散紀錄可能讓已成立訂單、可用庫存與待確認詢問不同步；固定資料只能示範檢查方式。','Distributed records may desynchronize confirmed orders, available stock, and pending inquiries; frozen data can only demonstrate the check.'):t('分散訊息可能造成待回覆與訂單資訊遺漏；需要在實際營運中量測。','Distributed messages may cause missed replies and order details; this needs measurement in live operations.')}</p></article><article><h3>${tag('owner')} ${t('仍缺資料','Missing information')}</h3><p>${t('沒有真實 IG／LINE、付款、電商或庫存系統連線；所有數量為固定示範 Fixture。','No real IG/LINE, payment, commerce, or inventory system is connected; every quantity is a frozen demo fixture.')}</p></article></div><div class="panel"><div class="panel-title"><div><p class="eyebrow">${t('建議的 AI 工作團隊','RECOMMENDED AI WORK TEAM')}</p><h2>${t('只建立目前需要的能力','Build only what is needed now')}</h2></div><span>${p.inquiry?t('1 個 AI Agent','1 AI agent'):t('0 個 AI Agent','0 AI agent')} · ${p.inventory?t('1 個自動化檢查','1 deterministic check'):t('0 個自動化檢查','0 deterministic check')}</span></div><div class="cap-row">${caps.join('')}</div><div class="stage-actions"><button class="secondary" data-action="backbrief">${t('修改探索內容','Revise discovery')}</button><button class="primary" data-action="approve">${t('Owner 核准此工作方案','Owner approve work plan')}</button></div></div></section>`}
 function artifact(id,p){let f=F.proposals[id],rule=id==='inquiry'?(p.externalApproval?t('所有外部訊息僅產出草稿，等待 Owner 核准。','All external messages stay as drafts pending Owner approval.'):t('從固定訊息整理訂單草稿與缺漏欄位。','Create order drafts and flag missing fields from frozen messages.')):(p.manualInventory?t('只比對資料與提出建議；禁止自動異動庫存。','Compare data and propose a recommendation only; automatic stock changes are prohibited.'):t('比對固定銷售與庫存紀錄，提出風險清單。','Compare frozen sales and inventory records and surface a risk list.'));return `<details class="artifact" open><summary><b>${T(f.name)}</b> ${tag(id==='inquiry'?'sim':'rule')}</summary><dl><dt>${t('工作目標','Goal')}</dt><dd>${T(f.problem)}</dd><dt>${t('固定資料','Frozen inputs')}</dt><dd>${T(f.inputs)}</dd><dt>${t('示例規則／指令','Example rule / instruction')}</dt><dd>${rule}</dd><dt>${t('交接','Handoff')}</dt><dd>${t('需要承諾、異動或對外訊息時交給 Owner。','Hand off to the Owner for commitments, changes, or external messages.')}</dd></dl></details>`}
 function build(){let p=P(),arts=[];if(p.inquiry)arts.push(artifact('inquiry',p));if(p.inventory)arts.push(artifact('inventory',p));let tests=[];if(p.inquiry)tests.push(`<article><b>${t('Order Desk 測試','Order Desk test')}</b><p>${t('輸入：IG／LINE 示範訊息。預期：ORD-IG-104 草稿、付款／交期缺漏、沒有對外發送。','Input: frozen IG/LINE messages. Expected: ORD-IG-104 draft, payment/delivery gaps, and no external send.')}</p><p>${s.tested?`<strong>${t('模擬結果：通過。','Simulated result: passed.')}</strong>`:t('尚未執行。','Not run yet.')}</p></article>`);if(p.inventory)tests.push(`<article><b>${t('Inventory Guardrail 測試','Inventory Guardrail test')}</b><p>${t('輸入：5 − 市集已售 2 − 已付款 LINE 訂單 2。預期：可用量 1；IG 詢問仍待確認。','Input: 5 − 2 market sales − 2 paid LINE units. Expected: 1 available; IG inquiry remains unconfirmed.')}</p><p>${s.tested?`<strong>${t('模擬結果：通過。','Simulated result: passed.')}</strong>`:t('尚未執行。','Not run yet.')}</p></article>`);let action=s.active?`<div><span class="stage">${t('已啟用','Active')}</span><p class="hint">${t('修改方案會使目前建置、測試與示範工作狀態失效。','Changing the plan invalidates current build, test, and demo work state.')}</p><button class="secondary" data-action="edit">${t('修改已啟用方案','Revise enabled plan')}</button></div>`:!s.build?`<button class="primary" data-action="build">${t('產生示範工作團隊配置','Generate demonstration team configuration')}</button>`:!s.tested?`<button class="primary" data-action="test">${t('執行固定測試案例','Run frozen test cases')}</button>`:`<button class="primary" data-action="activate">${t('Owner 啟用 AI 工作團隊','Owner activate AI work team')}</button>`;return `<section class="brief-stage"><div class="page-head"><div><p class="eyebrow">${t('階段三 · 建置、測試與啟用','PHASE 3 · BUILD, TEST & ACTIVATE')}</p><h1>${t('可檢視的 AI 工作團隊配置','Inspectable AI work-team configuration')}</h1><p>${t('以下是依核准方案產生的固定示範配置；不是已部署的外部 Agent。','The following is a frozen demo configuration generated from the approved plan; it is not a deployed external agent.')}</p></div>${tag('sim')}</div><div class="artifact-row">${arts.join('')}</div><div class="panel test-area"><div class="panel-title"><div><h2>${t('固定測試案例','Frozen test cases')}</h2><p>${t('建置、測試與啟用是三個不同狀態。','Build, test, and activation are three separate states.')}</p></div>${action}</div>${s.build?`<div class="test-row">${tests.join('')}</div>`:`<p class="muted">${t('先產生配置，再執行與所選能力相符的固定測試。','Generate the configuration first, then run frozen tests aligned with selected capabilities.')}</p>`}</div></section>`}
 function brief(){return futureDesks()+(s.setup==='conversation'?discovery():s.setup==='review'?review():build())}
 function teamCard(id,p,preview){let f=F.proposals[id],on=id==='inquiry'?p.inquiry:p.inventory;if(!on)return '';let isAgent=id==='inquiry';return `<article class="team-card"><div class="team-card-head"><span class="avatar">${isAgent?'AI':'↔'}</span><div><small>${isAgent?t('AI Agent','AI agent'):t('確定性自動化','Deterministic automation')}</small><h3>${T(f.name)}</h3></div>${preview?tag('preview'):tag(isAgent?'sim':'implemented')}</div><p>${T(f.output)}</p><div class="team-boundary"><b>${t('不會自行執行','Will not execute autonomously')}</b><span>${id==='inquiry'?t('不對客戶發送、不確認訂單、不承諾交期。','No external send, order confirmation, or delivery promise.'):t('不修改真實庫存、不接單、不採購。','No real stock change, order acceptance, or purchase.')}</span></div></article>`}
 function team(){let configured=P(),preview=!s.active,p=preview?demoPlan:configured,o=s.operation,stage={idle:preview?t('固定資料預覽','Frozen-data preview'):t('等待工作','Waiting for work'),triage:configured.inventory?t('Order Desk 已完成','Order Desk complete'):t('Order Desk 已完成','Order Desk complete'),inventory_ready:t('庫存比對待執行','Inventory check ready'),owner_pending:t('等待 Owner 決定','Waiting for Owner'),approved_pending:t('已核准，待執行','Approved, pending execution'),executed:t('今日示範工作完成','Today’s demo work complete')}[o];let start=o==='idle'?`<button class="primary" data-action="run" ${preview?'disabled':''}>${configured.inquiry?t('執行 Order Desk（模擬）','Run Order Desk (simulated)'):t('執行 Inventory Guardrail（模擬）','Run Inventory Guardrail (simulated)')}</button>`:['triage','inventory_ready'].includes(o)&&configured.inventory?`<button class="primary" data-action="checkstock">${t('執行庫存比對（模擬）','Run inventory check (simulated)')}</button>`:'';let flow=`<div class="flow-row"><span>${t('IG／LINE／市集示範資料','IG / LINE / market demo data')}</span><i>→</i><span>${t('Order Desk','Order Desk')}</span><i>→</i><span>${t('Owner Inbox','Owner Inbox')}</span><i>→</i><span>${t('Inventory Guardrail','Inventory Guardrail')}</span></div>`;let sec=`<section>${preview?`<div class="notice">${tag('preview')} ${t('這是預設 Retail Order Desk 的可瀏覽預覽；啟用後才會依核准方案執行。','This is a browseable preview of the default Retail Order Desk; execution follows the approved plan only after activation.')}</div>`:''}${s.toast?`<div class="toast">${t('AI 工作團隊已啟用。','AI work team activated.')}</div>`:''}<div class="page-head"><div><p class="eyebrow">${t('AI 工作團隊','MY AI TEAM')}</p><h1>${preview?t('Retail Order Desk：示範工作團隊','Retail Order Desk: demonstration work team'):t('你的 AI 工作團隊','Your AI work team')}</h1><p>${preview?t('先瀏覽產品如何運作；正式執行前仍須在商家設定中核准並啟用。','Browse how the product works first; approval and activation in Business Brief are still required before execution.'):t('這些能力只處理已核准範圍內的示範工作。','These capabilities process only frozen demo work within the approved scope.')}</p></div><div class="stage">${stage}</div></div><div class="team-row">${teamCard('inquiry',p,preview)}${teamCard('inventory',p,preview)}</div>${flow}<div class="two-cols"><div class="panel"><h2>${t('今日工作佇列','Today’s work queue')}</h2><div class="task"><code>MSG-01</code><span>${t('整理 IG／LINE 示範訊息','Triage synthetic IG/LINE messages')}</span><b>${o==='idle'?t('待處理','Pending'):t('完成','Complete')}</b></div><div class="task"><code>ORD-IG-104</code><span>${t('建立訂單草稿；缺付款／交期確認','Create order draft; payment/delivery missing')}</span><b>${o==='idle'?t('待處理','Pending'):t('待 Owner 確認','Owner review')}</b></div>${p.inventory?`<div class="task"><code>INV-01</code><span>${t('比對市集、已付款訂單與試算表','Compare market, paid-order, and spreadsheet records')}</span><b>${['triage','inventory_ready'].includes(o)?t('可執行','Ready'):o==='owner_pending'?t('待決定','Decision needed'):o==='executed'?t('完成','Complete'):t('等待','Waiting')}</b></div>`:''}${start}</div><div class="panel"><h2>${t('本次工作成果','Work product')}</h2>${o==='idle'?`<p class="muted">${t('執行後會保留原始示範輸入、訂單草稿、缺漏欄位與例外。','After execution, frozen inputs, order drafts, missing fields, and exceptions will remain visible here.')}</p>`:configured.inquiry?`<p><b>${t('Order Desk 輸出','Order Desk output')}</b><br>${t('ORD-IG-104 草稿：黃銅手鍊 2 件；付款與交期尚未確認；未對外發送。','ORD-IG-104 draft: 2 brass bracelets; payment and delivery not confirmed; nothing sent externally.')}</p>${o==='owner_pending'||o==='approved_pending'||o==='executed'?`<p><b>${t('Inventory Guardrail 輸出','Inventory Guardrail output')}</b><br>${t('可用量 1；IG 詢問 2 件仍不可承諾。','Availability 1; the IG inquiry for 2 units cannot yet be promised.')}</p>`:''}`:`<p><b>${t('Inventory Guardrail 輸出','Inventory Guardrail output')}</b><br>${t('可用量 1；需要 Owner 決定下一步。','Availability 1; the Owner must decide the next step.')}</p>`}<button class="secondary" data-modal="sources">${t('查看固定資料來源','View frozen data sources')}</button></div></div></section>`;return sec}
 function owner(){let active=s.active,o=s.operation,preview=!active,content=o==='owner_pending'?`<div class="decision"><div>${tag('owner')}<h2>${t('保留 IG 訂單，並核准示範庫存更新','Hold the IG order and approve the sample inventory update')}</h2><p>${t('已知：可用量為 1；IG 詢問 2 件尚未付款或確認交期。建議不做對外承諾。','Known: availability is 1; the IG inquiry for 2 units has no payment or delivery confirmation. Recommendation: make no external commitment.')}</p></div><button class="primary" data-action="approveop">${t('核准此示範操作','Approve this demo operation')}</button></div>`:o==='approved_pending'?`<div class="decision approved"><div>${tag('owner')}<h2>${t('已核准，待執行','Approved, pending execution')}</h2><p>${t('核准不代表庫存已更新，也不代表客戶已收到訊息。','Approval does not mean inventory has been updated or a customer has received a message.')}</p></div><button class="primary" data-action="executeop">${t('執行已核准操作（模擬）','Run approved operation (simulated)')}</button></div>`:o==='executed'?`<div class="decision completed">${tag('sim')}<h2>${t('示範操作已完成','Demo operation completed')}</h2><p>${t('試算表可用量更新為 1；ORD-IG-104 維持未確認草稿，沒有對外發送。','Spreadsheet availability is now 1; ORD-IG-104 remains an unconfirmed draft and was not sent externally.')}</p></div>`:`<div class="empty"><h2>${preview?t('預覽：下一個需要 Owner 的例外','Preview: the next Owner exception'):t('目前沒有待決事項','No decision is waiting')}</h2><p>${preview?t('完成庫存比對後，Owner 收件匣會顯示「可用量 1、IG 詢問 2 件」的例外與可選行動。','After inventory comparison, Owner Inbox will show the “1 available, 2 requested on IG” exception and its available actions.'):t('只有已啟用的 Inventory Guardrail 發現例外時，才會出現決定卡。','A decision card appears only when the enabled Inventory Guardrail finds an exception.')}</p></div>`;return `<section>${preview?`<div class="notice">${tag('preview')} ${t('這是 Owner Inbox 的固定資料預覽；沒有任何可執行操作。','This is a frozen-data Owner Inbox preview; no operation is executable.')}</div>`:''}<div class="page-head"><div><p class="eyebrow">${t('OWNER 收件匣','OWNER INBOX')}</p><h1>${t('把需要商業判斷的例外交給 Owner。','Route exceptions requiring business judgment to the Owner.')}</h1><p>${t('系統可以整理事實、草擬下一步並提示風險；承諾、庫存異動與對外訊息仍由 Owner 決定。','The system can organize facts, draft next steps, and flag risk; commitments, stock changes, and external messages remain with the Owner.')}</p></div></div>${content}<div class="two-cols"><div class="panel"><h2>${t('決策邊界','Decision boundary')}</h2><p>${t('不可自動對外傳送訊息、確認訂單、承諾交期、採購或更改真實庫存。','No automatic external message, order confirmation, delivery promise, purchase, or real inventory change.')}</p><button class="secondary" data-modal="policy">${t('查看規則','View rules')}</button></div><div class="panel"><h2>${t('稽核紀錄','Audit trail')}</h2>${s.audit.length?s.audit.map(a=>`<div class="audit"><code>${a.id}</code> ${T(a.text)}</div>`).join(''):`<p class="muted">${t('尚無執行紀錄。','No execution record yet.')}</p>`}</div></div></section>`}
 function pulse(){let c=C.costs(s),preview=!s.active;return `<section>${preview?`<div class="notice">${tag('preview')} ${t('下列為固定 Retail fixture 的營運摘要，不代表真實商業成效或 ROI。','The following is the frozen Retail fixture summary, not real business performance or ROI.')}</div>`:''}<div class="page-head"><div><p class="eyebrow">${t('營運脈動','BUSINESS PULSE')}</p><h1>${t('今日工作成果、待確認訂單與固定示範交易','Today’s work, pending order, and frozen sample transactions')}</h1><p>${t('重點是看工作狀態與例外，而不是宣稱模擬已創造真實 ROI。','The emphasis is work state and exceptions, not a claim that simulation created real ROI.')}</p></div></div><div class="pulse-row"><div><small>${t('示範待確認訂單','Sample pending order')}</small><b>1</b><span>ORD-IG-104</span></div><div><small>${t('需要 Owner 決定','Needs Owner decision')}</small><b>${['owner_pending','approved_pending'].includes(s.operation)?1:0}</b><span>${t('庫存例外','Stock exception')}</span></div><div><small>${t('示範已成立銷售','Frozen confirmed sales')}</small><b>${nt(c.revenue)}</b><span>${t('不含待確認訂單','Excludes pending order')}</span></div><div><small>${t('模擬整理成本','Simulated triage cost')}</small><b>${nt(c.simulatedOps)}</b><span>${c.simulatedOps?t('示範操作後才計入','Included after demo operation'):t('尚未發生','Not incurred')}</span></div></div><div class="two-cols"><div class="panel"><h2>${t('固定示範交易 ledger','Frozen transaction ledger')}</h2><table><tbody><tr><td>${t('市集銷售','Market sales')}</td><td>2 × ${nt(680)}</td><td>${nt(1360)}</td></tr><tr><td>${t('已付款 LINE 訂單','Paid LINE order')}</td><td>2 × ${nt(680)}</td><td>${nt(1360)}</td></tr><tr><td>${t('材料成本','Material cost')}</td><td>4 × ${nt(240)}</td><td>−${nt(960)}</td></tr><tr><td>${t('市集費用','Market fee')}</td><td></td><td>−${nt(240)}</td></tr><tr><td>${t('示範已實現貢獻','Frozen realized contribution')}</td><td></td><td><b>${nt(c.contribution)}</b></td></tr></tbody></table></div><div class="panel"><h2>${t('不可當成 ROI 的事項','What this is not')}</h2><ul><li>${t('ORD-IG-104 的 NT$1,360 尚未確認，不計入收入或貢獻。','NT$1,360 from ORD-IG-104 is not confirmed, so it is excluded from revenue and contribution.')}</li><li>${t('沒有量測工時節省、轉換率或真實商業提升。','No time saving, conversion, or real business uplift has been measured.')}</li><li>${t('所有資料均為可重現的固定 Fixture。','All data is a repeatable frozen fixture.')}</li></ul><button class="secondary" data-modal="calc">${t('查看計算方式','View calculation')}</button></div></div></section>`}
 function modal(type,b){modalTrigger=b;let body=type==='retail'?`<h2>${t('Retail Order Desk','Retail Order Desk')}</h2><p>${t('目前唯一可操作的示範：將社群詢問、訂單草稿與庫存例外整理成 Owner 可處理的每日工作。','The only interactive demonstration: turn social inquiries, order drafts, and stock exceptions into daily work the Owner can handle.')}</p>`:type==='translator'?`<h2>${t('Translation Delivery Desk','Translation Delivery Desk')}</h2><p>${tag('planned')} ${t('未來範例：文件輸入 → 術語與 QA 例外 → Owner 審閱 → 交付。保留相同的 Business Brief、AI Team、Owner Inbox 與 Business Pulse 核心。','Future example: document input → terminology and QA exceptions → Owner review → delivery. It reuses the same Business Brief, AI Team, Owner Inbox, and Business Pulse core.')}</p>`:type==='designer'?`<h2>${t('Creative Project Desk','Creative Project Desk')}</h2><p>${tag('planned')} ${t('未來範例：brief 與素材 → feedback 整理 → Owner 創意決策 → 交付追蹤。這不是目前可執行的第二個 scenario。','Future example: brief and assets → feedback triage → Owner creative decision → delivery tracking. It is not a second executable scenario today.')}</p>`:type==='sources'?`<h2>${t('固定資料來源','Frozen data sources')}</h2>${Object.values(F.records).map(r=>`<p><code>${r.id}</code> ${T(r)}</p>`).join('')}<p>${tag('sim')} ${t('沒有 IG、LINE、電商、付款或試算表連線。','No IG, LINE, commerce, payment, or spreadsheet connection exists.')}</p>`:type==='policy'?`<h2>${t('Owner 規則','Owner rules')}</h2><ul><li>${t('外部訊息一律維持草稿，需 Owner 核准。','External messages remain drafts and need Owner approval.')}</li><li>${t('不可自動確認訂單、承諾交期、採購或更改真實庫存。','No automatic order confirmation, delivery promise, purchase, or real inventory change.')}</li><li>${t('Owner 核准只允許模擬執行；不代表操作已完成。','Owner approval permits simulated execution only; it does not mean the operation is complete.')}</li></ul>`:`<h2>${t('固定示範計算','Frozen demo calculation')}</h2><div class="formula">${nt(2720)} ${t('收入','revenue')}<br>− ${nt(960)} ${t('材料成本','material cost')}<br>− ${nt(240)} ${t('市集費用','market fee')}<br>− ${nt(C.costs(s).simulatedOps)} ${t('模擬整理成本','simulated triage cost')}<hr>= <strong>${nt(C.costs(s).contribution)} ${t('固定示範貢獻','frozen demo contribution')}</strong></div>`;let el=document.createElement('div');el.className='modal-wrap';el.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${t('詳細內容','Details')}"><button class="close" data-close aria-label="${t('關閉','Close')}">×</button>${body}</div>`;document.body.append(el);document.body.classList.add('modal-open');el.querySelector('.close').focus()}
 function close(){document.querySelector('.modal-wrap')?.remove();document.body.classList.remove('modal-open');modalTrigger?.focus()}
 function handle(e){let b=e.target.closest?.('[data-go],[data-action],[data-intent],[data-modal],[data-close]');if(!b)return;if(b.dataset.close!==undefined||b.classList.contains('modal-wrap')){close();return}if(b.dataset.go){go(b.dataset.go);return}if(b.dataset.modal){modal(b.dataset.modal,b);return}if(b.dataset.intent){let x={inquiry:t('IG 和 LINE 詢問很多，常常漏回覆，也要花時間整理訂單。','IG and LINE inquiries are easy to miss, and order triage takes time.'),inventory:t('市集賣完常沒更新試算表，線上庫存會對不起來。','Market sales are not always entered in the spreadsheet, so online inventory is out of sync.'),control:t('庫存我自己管，所有對外訊息都要我確認。','I manage inventory myself, and I must approve every external message.')}[b.dataset.intent];act({type:'say',text:x});return}let a=b.dataset.action;if(a==='lang'){s.lang=s.lang==='zh'?'en':'zh';save();render()}else if(a==='reset'){s=C.initial();save();go('brief')}else if(a==='sample')act('sampleConversation');else if(a==='review')act('reviewPlan');else if(a==='backbrief')act('backToChat');else if(a==='approve')act('approveProposal');else if(a==='build')act('build');else if(a==='test')act('test');else if(a==='activate')act('activate');else if(a==='edit')act('editPlan');else if(a==='run')act('startOperation');else if(a==='checkstock')act('detectConflict');else if(a==='approveop')act('approveOperation');else if(a==='executeop')act('executeOperation')}
 document.addEventListener('click',handle);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});document.addEventListener('DOMContentLoaded',()=>{load();let h=location.hash.slice(1);if(['brief','team','owner','pulse'].includes(h))s.screen=h;else if(s.screen==='onboard')s.screen='brief';render()});window.addEventListener('hashchange',()=>{let h=location.hash.slice(1);if(['brief','team','owner','pulse'].includes(h)&&s.screen!==h)go(h,false)});
 document.addEventListener('click',e=>{if(e.target.classList?.contains('modal-wrap'))close()});
})();
